"""Natural Earth-derived boundaries used for SFR building asset regions.

Generated from Natural Earth public domain GeoJSON:
- ne_110m_admin_0_countries.geojson, version 5.1.1
- ne_50m_admin_1_states_provinces.geojson, version 5.1.1

Only region key, source id/name, bbox, and polygon rings are retained.
Coordinates are WGS84 lon/lat rounded to 5 decimal places.
"""


def _point_in_ring(lon, lat, ring):
    """Return True when a lon/lat point is inside one polygon ring."""
    inside = False
    j = len(ring) - 1
    for i, (xi, yi) in enumerate(ring):
        xj, yj = ring[j]
        if ((yi > lat) != (yj > lat)):
            x_at_lat = ((xj - xi) * (lat - yi) / ((yj - yi) or 1e-12)) + xi
            if lon < x_at_lat:
                inside = not inside
        j = i
    return inside


def _point_in_polygon_rings(lon, lat, rings):
    """Return True when a point is in the exterior and outside any holes."""
    if not rings or not _point_in_ring(lon, lat, rings[0]):
        return False
    return not any(_point_in_ring(lon, lat, hole) for hole in rings[1:])

