REGION_BOUNDARIES = ADMIN1_REGION_BOUNDARIES + ADMIN0_REGION_BOUNDARIES


def asset_region_for_latlon(lat, lon):
    """Return the SFR asset region key from Natural Earth boundary polygons."""
    for region_key, _, _, bbox, rings in REGION_BOUNDARIES:
        lon_w, lat_s, lon_e, lat_n = bbox
        if lon_w <= lon <= lon_e and lat_s <= lat <= lat_n:
            if _point_in_polygon_rings(lon, lat, rings):
                return region_key
    return "generic"
